begin;
create table internal.intervention_approved_options(school_id uuid not null,intervention_id uuid not null,activity_id uuid not null,decision_id uuid not null,title text not null,instructions text not null,sequence integer not null check(sequence between 1 and 3),primary key(school_id,intervention_id,activity_id),unique(school_id,intervention_id,sequence),foreign key(school_id,intervention_id)references app.interventions(school_id,id),foreign key(school_id,activity_id)references app.activities(school_id,id),foreign key(school_id,decision_id)references app.human_decisions(school_id,id));
create table internal.intervention_learning_choices(school_id uuid not null,intervention_id uuid not null,activity_id uuid not null,learner_id uuid not null,chosen_at timestamptz not null default clock_timestamp(),primary key(school_id,intervention_id),foreign key(school_id,intervention_id,activity_id)references internal.intervention_approved_options(school_id,intervention_id,activity_id),foreign key(school_id,intervention_id,learner_id)references app.interventions(school_id,id,learner_id));
alter table app.intervention_completions add column chosen_activity_id uuid;
alter table app.intervention_completions add foreign key(school_id,chosen_activity_id)references app.activities(school_id,id);
do $$declare tab text;begin foreach tab in array array['intervention_approved_options','intervention_learning_choices']loop
 execute format('alter table internal.%I enable row level security',tab);execute format('alter table internal.%I force row level security',tab);execute format('create trigger approved_choice_immutable before update or delete on internal.%I for each row execute function internal.academic_history_immutable()',tab);execute format('create trigger approved_choice_no_truncate before truncate on internal.%I for each statement execute function internal.academic_history_immutable()',tab);execute format('revoke all on internal.%I from public,anon,authenticated,service_role,cuevo_api,cuevo_worker',tab);
end loop;end$$;
create function internal.intervention_option_current(target uuid,activity uuid)returns boolean language sql stable security definer set search_path=''as $$
 select coalesce(exists(select 1 from internal.intervention_approved_options option join app.interventions task on task.school_id=option.school_id and task.id=option.intervention_id join app.recommendations proposal on proposal.school_id=task.school_id and proposal.id=task.recommendation_id join app.intelligence_runs run on run.school_id=proposal.school_id and run.id=proposal.intelligence_run_id join app.intelligence_policies policy on policy.school_id=run.school_id and policy.version=run.policy_version join app.result_revisions baseline on baseline.school_id=task.school_id and baseline.id=task.baseline_result_id join app.assessments assessment on assessment.school_id=baseline.school_id and assessment.id=baseline.assessment_id join app.activities source on source.school_id=option.school_id and source.id=option.activity_id join app.lessons lesson on lesson.school_id=source.school_id and lesson.id=source.lesson_id join app.units unit on unit.school_id=lesson.school_id and unit.id=lesson.unit_id join app.courses course on course.school_id=unit.school_id and course.id=unit.course_id
 where option.school_id="authorization".school_id()and option.intervention_id=target and option.activity_id=activity and unit.course_id=assessment.course_id and course.status='PUBLISHED'and source.kind='practice'and source.title=option.title and source.instructions=option.instructions and not internal.intervention_requires_review(task.school_id,task.id)
 and'GUIDED_PRACTICE'=any(policy.allowed_actions)and((run.generation_mode='FIXTURE'and policy.fixture_enabled)or(run.generation_mode='LIVE'and policy.live_enabled))and"authorization".programme_course_allowed(task.school_id,course.id,task.learner_id)and("authorization".can_access_intervention(task.school_id,task.id,true)or("authorization".current_role(task.school_id)='student'and task.learner_id="authorization".actor_id()and"authorization".can_learn_course(task.school_id,course.id)))),false)
$$;
create function internal.decide_recommendation(target uuid,choice text,reason_text text,edited_title text,edited_instructions text,learner_note text,approved_activities uuid[])returns uuid language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();proposal app.recommendations;run app.intelligence_runs;stored jsonb;activity_id uuid;activity jsonb;decision app.human_decisions;task app.interventions;existing uuid[];ordinal integer:=0;result uuid;begin
 if approved_activities is null or cardinality(approved_activities)>3 or cardinality(approved_activities)<>(select count(distinct selected.id)from unnest(approved_activities)selected(id))or array_position(approved_activities,null)is not null or(choice is distinct from'APPROVE'and cardinality(approved_activities)>0)then raise exception 'Bounded explicit approved options required'using errcode='22023';end if;
 select*into proposal from app.recommendations where school_id=school and id=target for update;
 if not found or not"authorization".can_manage_baseline(school,proposal.baseline_result_id)then raise exception 'Approved option source denied'using errcode='42501';end if;
 if cardinality(approved_activities)>0 then
  if proposal.intelligence_run_id is null then raise exception 'Saved authorized option context required'using errcode='22023';end if;
  perform internal.require_stored_insight_scope(proposal.intelligence_run_id);select*into run from app.intelligence_runs where school_id=school and id=proposal.intelligence_run_id;
  if run.allowed_actions is null or not('GUIDED_PRACTICE'=any(run.allowed_actions))then raise exception 'Guided practice policy required'using errcode='22023';end if;
  select context into stored from app.intelligence_context_details where school_id=school and run_id=run.id;
  perform 1 from app.activities source where source.school_id=school and source.id=any(approved_activities)order by source.id for share;
  foreach activity_id in array approved_activities loop
   select source into activity from jsonb_array_elements(stored->'learningOptions')source where source->>'activityId'=activity_id::text and source->>'kind'='practice';
   if activity is null or not exists(select 1 from app.activities source where source.school_id=school and source.id=activity_id and source.kind='practice'and source.title=activity->>'title'and source.instructions=activity->>'instructions')then raise exception 'Exact saved practice required'using errcode='42501';end if;
  end loop;
 end if;
 select*into decision from app.human_decisions where school_id=school and recommendation_id=target;
 if decision.id is not null then select*into task from app.interventions where school_id=school and recommendation_id=target;select coalesce(array_agg(option.activity_id order by option.sequence),array[]::uuid[])into existing from internal.intervention_approved_options option where option.school_id=school and option.intervention_id=task.id;if existing is distinct from approved_activities then raise exception 'Approved alternatives immutable'using errcode='22023';end if;end if;
 result:=internal.decide_recommendation(target,choice,reason_text,edited_title,edited_instructions,learner_note);
 if decision.id is null and cardinality(approved_activities)>0 then
  select*into decision from app.human_decisions where school_id=school and recommendation_id=target;select*into task from app.interventions where school_id=school and recommendation_id=target;
  foreach activity_id in array approved_activities loop
   select source into activity from jsonb_array_elements(stored->'learningOptions')source where source->>'activityId'=activity_id::text;
   ordinal:=ordinal+1;insert into internal.intervention_approved_options(school_id,intervention_id,activity_id,decision_id,title,instructions,sequence)values(school,task.id,activity_id,decision.id,activity->>'title',activity->>'instructions',ordinal);
  end loop;
 end if;return result;
end$$;
create function internal.read_intervention_choices(target uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();task app.interventions;options jsonb;choice jsonb;begin
 select*into task from app.interventions where school_id=school and id=target;
 if not found or not internal.intervention_history_allowed(school,target)or"authorization".current_role(school)not in('teacher','admin','student')or("authorization".current_role(school)='student'and task.learner_id<>"authorization".actor_id())then raise exception 'Approved choice read denied'using errcode='42501';end if;
 select coalesce(jsonb_agg(jsonb_build_object('activityId',option.activity_id,'title',option.title,'instructions',option.instructions,'available',internal.intervention_option_current(target,option.activity_id))order by option.sequence),'[]'::jsonb)into options from internal.intervention_approved_options option where option.school_id=school and option.intervention_id=target;
 select jsonb_build_object('activityId',selected.activity_id,'title',option.title,'instructions',option.instructions,'chosenAt',selected.chosen_at)into choice from internal.intervention_learning_choices selected join internal.intervention_approved_options option on option.school_id=selected.school_id and option.intervention_id=selected.intervention_id and option.activity_id=selected.activity_id where selected.school_id=school and selected.intervention_id=target;
 return jsonb_build_object('id',target,'interventionId',target,'options',options,'choice',choice);
end$$;
create function internal.choose_intervention_activity(target uuid,input jsonb,command_key text,fingerprint text,request_id text)returns void language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();task app.interventions;activity uuid;reservation jsonb;begin
 if input is null or jsonb_typeof(input)<>'object'or not(input?&array['activityId','confirmChoice'])or input-'activityId'-'confirmChoice'<>'{}'::jsonb or input->'confirmChoice'is distinct from'true'::jsonb or jsonb_typeof(input->'activityId')is distinct from'string'then raise exception 'Explicit approved source choice required'using errcode='22023';end if;
 begin activity:=(input->>'activityId')::uuid;exception when invalid_text_representation then raise exception 'Choice identity invalid'using errcode='22023';end;
 select*into task from app.interventions where school_id=school and id=target for update;
 if task.id is null then raise exception 'Current assigned task required'using errcode='42501';end if;
 perform 1 from app.activities source where source.school_id=school and source.id=activity for share;
 if not found or"authorization".current_role(school)<>'student'or task.learner_id<>"authorization".actor_id()or not"authorization".can_access_intervention(school,target,false)or not internal.intervention_option_current(target,activity)then raise exception 'Current approved practice choice denied'using errcode='42501';end if;
 reservation:=internal.begin_command(command_key,'intervention.activity.choose',fingerprint);if reservation->>'state'='COMPLETED'then return;end if;if reservation->>'state'<>'NEW'then raise exception 'Choice command in progress'using errcode='22023';end if;
 if task.status<>'ASSIGNED'or exists(select 1 from internal.intervention_learning_choices where school_id=school and intervention_id=target)then raise exception 'Learner choice immutable or task closed'using errcode='22023';end if;
 insert into internal.intervention_learning_choices(school_id,intervention_id,activity_id,learner_id)values(school,target,activity,task.learner_id);
 perform internal.append_audit('intervention.activity.chosen','intervention',target,request_id,'succeeded',jsonb_build_object('activityId',activity));perform internal.enqueue_event('intervention.activity.chosen','intervention',target,1,jsonb_build_object('activityId',activity),'intervention-choice:'||target::text);
 perform internal.finish_command(command_key,'intervention.activity.choose',fingerprint,jsonb_build_object('id',target,'activityId',activity));
end$$;
create function internal.complete_intervention_choice_source()returns trigger language plpgsql security definer set search_path=''as $$declare activity uuid;begin
 select activity_id into activity from internal.intervention_learning_choices where school_id=new.school_id and intervention_id=new.intervention_id;
 if activity is not null and not internal.intervention_option_current(new.intervention_id,activity)then raise exception 'Chosen practice source changed'using errcode='42501';end if;
 new.chosen_activity_id:=activity;return new;
end$$;
create trigger intervention_completion_choice_source before insert on app.intervention_completions for each row execute function internal.complete_intervention_choice_source();
do $$declare definition text;anchor text;begin
 definition:=pg_get_functiondef('internal.process_learner_event(uuid,uuid)'::regprocedure);anchor:='begin'||chr(10);if position(anchor in definition)=0 then raise exception 'Choice event dispatcher changed'using errcode='22023';end if;
 definition:=replace(definition,anchor,'begin'||chr(10)||' if exists(select 1 from internal.outbox_events event where event.id=target_event and event.type=''intervention.activity.chosen'')then select*into e from internal.outbox_events where id=target_event for update;if e.state<>''PROCESSING''or e.lease_token is distinct from current_lease or e.lease_until<=clock_timestamp()or e.version<>1 or e.entity_type<>''intervention''or not exists(select 1 from internal.intervention_learning_choices source where source.school_id=e.school_id and source.intervention_id=e.entity_id and source.learner_id=e.actor_id and source.activity_id::text=e.metadata->>''activityId'')then raise exception ''Choice event source invalid''using errcode=''22023'';end if;insert into internal.processed_events(event_id,school_id)values(e.id,e.school_id)on conflict(event_id)do nothing;if internal.complete_outbox(e.id,current_lease)is distinct from true then raise exception ''Choice event lease changed''using errcode=''22023'';end if;return jsonb_build_object(''status'',''ACKNOWLEDGED'');end if;'||chr(10));execute definition;
end$$;
revoke execute on function internal.intervention_option_current(uuid,uuid),internal.decide_recommendation(uuid,text,text,text,text,text,uuid[]),internal.read_intervention_choices(uuid),internal.choose_intervention_activity(uuid,jsonb,text,text,text),internal.complete_intervention_choice_source()from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant execute on function internal.decide_recommendation(uuid,text,text,text,text,text,uuid[]),internal.read_intervention_choices(uuid),internal.choose_intervention_activity(uuid,jsonb,text,text,text)to cuevo_api;
commit;
